from collections import deque

def transform(grid):
    rows, cols = len(grid), len(grid[0])

    floor_row = rows - 1
    for r in range(rows - 1, -1, -1):
        if all(grid[r][c] == grid[r][0] for c in range(cols)):
            floor_row = r
            break

    floor_val = grid[floor_row][0]

    visited = set()
    components = []

    for r in range(floor_row):
        for c in range(cols):
            if grid[r][c] != 0 and (r, c) not in visited:
                val = grid[r][c]
                q = deque([(r, c)])
                visited.add((r, c))
                cell_list = [(r, c)]

                while q:
                    cr, cc = q.popleft()
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == val and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            cell_list.append((nr, nc))
                            q.append((nr, nc))

                min_c = min(cc for cr, cc in cell_list)
                max_c = max(cc for cr, cc in cell_list)
                crow_list = sorted(set(cr for cr, cc in cell_list))

                comp = {'val': val, 'min_c': min_c, 'width': max_c - min_c + 1}
                comp['height'] = len(crow_list)
                comp['min_r'] = crow_list[0]
                components.append(comp)

    sorted_by_min_r = sorted(components, key=lambda x: (x['min_r'], x['min_c'], x['val']))
    h2_comps = [c for c in sorted_by_min_r if c['height'] == 2]
    h1_w2_comps = [c for c in sorted_by_min_r if c['height'] == 1 and c['width'] == 2]

    print(f"h2_comps: {[(c['val'], c['min_c'], c['min_r']) for c in h2_comps]}")
    print(f"h1_w2_comps: {[(c['val'], c['min_c'], c['min_r']) for c in h1_w2_comps]}")

    output = [[0] * cols for _ in range(rows)]
    output[floor_row] = [floor_val] * cols

    # h2 bands grouped by min_r
    h2_by_minr = {}
    for comp in h2_comps:
        if comp['min_r'] not in h2_by_minr:
            h2_by_minr[comp['min_r']] = []
        h2_by_minr[comp['min_r']].append(comp)
    bands = [h2_by_minr[min_r] for min_r in sorted(h2_by_minr.keys())]

    for band_idx, band in enumerate(bands):
        if band_idx == 0:
            target_row = floor_row - 3
            for c in range(cols):
                for comp in band:
                    if c >= comp['min_c'] and c < comp['min_c'] + comp['width']:
                        output[target_row][c] = comp['val']
        else:
            target_row = floor_row - 2
            for c in range(cols):
                for comp in band:
                    if c >= comp['min_c'] and c < comp['min_c'] + comp['width']:
                        output[target_row][c] = comp['val']

    # h1_w2 in floor_row-1
    for c in range(cols):
        for comp in h1_w2_comps:
            if c >= comp['min_c'] and c < comp['min_c'] + comp['width']:
                output[floor_row - 1][c] = comp['val']

    return output

